import {FORMA_LANGUAGES,currentLanguage,currentLocale,setLanguage,t,translateTree} from './i18n.js';
const modal=document.querySelector('#commerce-modal'),body=document.querySelector('#commerce-body');
const BILLING_KEY='forma-billing',ADS_KEY='fitness-copilot-ads';
const AD_POLICY={actionsPerInterstitial:4,cooldownMs:300000,dailyInterstitialLimit:3,bannerRoutes:['home','exercise','plan']};
let billing={plan:'yearly',...(JSON.parse(localStorage.getItem(BILLING_KEY)||'{}'))},paywallReason='manual',nativeAds=null;
const tr=source=>t(source),close=()=>modal.close(),saveBilling=()=>localStorage.setItem(BILLING_KEY,JSON.stringify(billing));
const isPro=()=>billing.status==='active'||(billing.status==='trial'&&new Date(billing.trialEnd).getTime()>Date.now());
function show(content){body.innerHTML=content;translateTree(body);if(!modal.open)modal.showModal();}
function paywall(reason='manual'){
 paywallReason=reason;const atlas=reason==='atlas',onboarding=reason==='onboarding';
 show(`<div class="commerce-sheet pro-paywall"><div class="commerce-hero"><button class="commerce-close" data-commerce="dismiss-paywall" aria-label="Kapat">×</button><span class="commerce-kicker">Fitness Copilot PRO · ${tr('7 gün ücretsiz dene')}</span><h2>${tr(atlas?'Kas Atlası PRO ile açılır.':onboarding?'Planın hazır. Şimdi PRO’yu ücretsiz dene.':'Daha kişisel. Daha ölçülebilir.')}</h2><p>${tr(atlas?'467 anatomik yapıyı incele, kasa dokun ve o kası çalıştıran hareketleri bul.':'İlk 7 gün ücretsiz. Akıllı planlama, Kas Atlası ve reklamsız antrenman deneyimini keşfet.')}</p><div class="trial-promise"><strong>${tr('Bugün ödeme yok')}</strong><span>${tr('7 gün boyunca ücretsiz · İstediğin zaman iptal')}</span></div><div class="benefit-grid"><div class="benefit"><strong>◉ ${tr('Akıllı Koç')}</strong><small>${tr('RPE/RIR, hacim ve gelişim içgörüleri')}</small></div><div class="benefit"><strong>◈ Atlas Pro</strong><small>${tr('Kas ısı haritası ve gelişmiş anatomi')}</small></div><div class="benefit"><strong>∞ ${tr('Sınırsız plan')}</strong><small>${tr('Özel programlar ve ekipman profilleri')}</small></div><div class="benefit"><strong>⊘ ${tr('Reklamsız')}</strong><small>${tr('Kesintisiz keşif ve antrenman')}</small></div></div><div class="price-choice"><button class="price-card ${billing.plan==='yearly'?'selected':''}" data-commerce="plan" data-value="yearly"><span>${tr('Yıllık · %44 avantaj')}</span><b>₺999,99 / ${tr('yıl')}</b><small>₺83,33 / ${tr('ay')}</small></button><button class="price-card ${billing.plan==='monthly'?'selected':''}" data-commerce="plan" data-value="monthly"><span>${tr('Aylık')}</span><b>₺149,99 / ${tr('ay')}</b><small>${tr('7 gün ücretsiz')}</small></button></div><button class="trial-button" data-commerce="trial">${tr('7 günlük ücretsiz denemeyi başlat')}</button><p class="billing-terms">${tr('Bugün ödeme yok. 7 gün sonra yıllık planda ₺999,99/yıl veya aylık planda ₺149,99/ay. Seçtiğin plan, deneme bitmeden iptal etmezsen otomatik yenilenir.')} ${tr('App Store/Google Play ayarlarından istediğin zaman iptal edebilirsin. Deneme bitmeden 24 saat önce hatırlatma seçeneği üyelik ekranında sunulur.')}</p><div class="billing-links"><button data-commerce="manage">${tr('Üyeliği yönet')}</button><button data-commerce="restore">${tr('Satın almayı geri yükle')}</button></div></div>`);
}
function languages(){show(`<div class="commerce-sheet"><div class="commerce-hero"><button class="commerce-close" data-commerce="close" aria-label="Kapat">×</button><span class="commerce-kicker">Fitness Copilot · GLOBAL</span><h2>${tr('Dilini seç')}</h2></div><div class="language-grid" data-i18n-ignore>${Object.entries(FORMA_LANGUAGES).map(([code,item])=>`<button class="language-option ${code===currentLanguage()?'active':''}" data-commerce="set-language" data-value="${code}"><strong>${item.native}</strong><small>${item.name}</small></button>`).join('')}</div></div>`)}
function membership(){const end=isPro()&&billing.trialEnd?new Date(billing.trialEnd):null;show(`<div class="commerce-sheet"><div class="commerce-hero"><button class="commerce-close" data-commerce="close" aria-label="Kapat">×</button><span class="commerce-kicker">Fitness Copilot PRO</span><h2>${tr('Üyeliği yönet')}</h2>${end?`<div class="membership-card"><strong>${tr('Denemen aktif')}</strong><small>${end.toLocaleDateString(currentLocale())} ${tr('tarihine kadar ücretsiz')}</small><div class="trial-line"><i style="width:14%"></i></div><label><input type="checkbox" data-commerce="reminder" ${billing.reminder?'checked':''}> ${tr('Deneme bitmeden 24 saat önce hatırlat')}</label></div>`:`<p>${tr('Aktif üyelik veya deneme bulunmuyor.')}</p>`}<button class="trial-button" data-commerce="close">${tr('Tamam')}</button></div></div>`)}
function adState(){const today=new Date().toISOString().slice(0,10),saved=JSON.parse(localStorage.getItem(ADS_KEY)||'{}');return saved.day===today?saved:{day:today,views:0,actions:0,last:0,onboardingShown:false};}
function saveAds(value){localStorage.setItem(ADS_KEY,JSON.stringify(value));}
function adSafe(){const appState=JSON.parse(localStorage.getItem('forma-v1')||'{}');return !isPro()&&!appState.activeSession&&!document.querySelector('#modal[open]')&&!modal.open;}
function showInterstitial(source='navigation',force=false){
 const ads=adState(),now=Date.now();if(!adSafe()||ads.views>=AD_POLICY.dailyInterstitialLimit||(!force&&(ads.actions<AD_POLICY.actionsPerInterstitial||now-ads.last<AD_POLICY.cooldownMs)))return false;
 ads.views++;ads.actions=0;ads.last=now;if(source==='onboarding')ads.onboardingShown=true;saveAds(ads);
 if(nativeAds?.showInterstitial){nativeAds.showInterstitial({placement:source});return true;}
 show(`<div class="commerce-sheet interstitial-ad"><div class="ad-screen-label">${tr('REKLAM')}</div><div class="ad-creative"><span>FITNESS COPILOT PARTNER</span><h2>${tr('Antrenman ekipmanlarında üyeye özel fırsat')}</h2><p>${tr('Reklam, aktif antrenman sırasında gösterilmez.')}</p><button data-commerce="ad">${tr('Keşfet')}</button></div><button class="secondary full" data-commerce="close">${tr('Reklamı kapat')}</button></div>`);return true;
}
function noteEligibleAction(source='navigation'){if(!adSafe())return;const ads=adState();ads.actions++;saveAds(ads);showInterstitial(source);}
function injectAd(){document.querySelector('.ad-slot')?.remove();}
new MutationObserver(()=>{clearTimeout(window.__fitnessAd);window.__fitnessAd=setTimeout(injectAd,120)}).observe(document.querySelector('#app'),{childList:true,subtree:true});
window.addEventListener('fitness:onboarding-complete',()=>setTimeout(()=>paywall('onboarding'),180));
window.addEventListener('fitness:eligible-action',event=>noteEligibleAction(event.detail?.source));
document.addEventListener('click',event=>{const button=event.target.closest('[data-commerce]');if(!button)return;const action=button.dataset.commerce;if(action==='paywall')paywall('manual');if(action==='language')languages();if(action==='close')close();if(action==='dismiss-paywall'){const reason=paywallReason;close();if(reason==='onboarding'){const ads=adState();if(!ads.onboardingShown)setTimeout(()=>showInterstitial('onboarding',true),180);}}if(action==='plan'){billing.plan=button.dataset.value;paywall(paywallReason)}if(action==='set-language'&&setLanguage(button.dataset.value)){close();location.reload()}if(action==='trial'){const native=window.Capacitor?.isNativePlatform?.();if(native){close();window.dispatchEvent(new window.CustomEvent('forma:checkout',{detail:{product:billing.plan,trialDays:7}}));}else{billing={...billing,status:'trial',trialStarted:new Date().toISOString(),trialEnd:new Date(Date.now()+7*864e5).toISOString(),reminder:true};saveBilling();window.dispatchEvent(new window.CustomEvent('forma:checkout',{detail:{product:billing.plan,trialDays:7}}));close();window.dispatchEvent(new window.CustomEvent('fitness:entitlement-change'));membership();}}if(action==='manage')membership();if(action==='restore'){if(window.Capacitor?.isNativePlatform?.())window.dispatchEvent(new window.CustomEvent('fitness:restore-purchases'));else alert(tr('Satın alma geri yükleme işlemi mobil uygulamada kullanılabilir.'));}if(action==='ad')alert(tr('Sponsor bağlantısı güvenli uygulama içi sayfada açılacak.'));});
modal.addEventListener('click',event=>{if(event.target===modal&&!body.querySelector('[data-first-language],.pro-paywall'))close()});
document.addEventListener('change',event=>{if(event.target.dataset.commerce==='reminder'){billing.reminder=event.target.checked;saveBilling()}});
window.FORMA_BILLING={getState:()=>({...billing}),getAdPolicy:()=>({...AD_POLICY,bannerRoutes:[...AD_POLICY.bannerRoutes]}),isPro,requestPro:paywall,noteEligibleAction,setAdAdapter:adapter=>{nativeAds=adapter;injectAd()},startCheckout:adapter=>adapter({product:billing.plan,trialDays:7}),setEntitlement:(status,expiresAt)=>{billing={...billing,status,expiresAt};saveBilling();window.dispatchEvent(new window.CustomEvent('fitness:entitlement-change'))}};
setTimeout(injectAd,300);
